package com.acme.support.channel;

import com.fasterxml.jackson.core.type.TypeReference;
import jakarta.validation.Valid;
import jakarta.validation.constraints.*;
import org.springframework.http.*;
import org.springframework.security.core.Authentication;
import org.springframework.stereotype.Controller;
import org.springframework.ui.Model;
import org.springframework.validation.BindingResult;
import org.springframework.web.bind.annotation.*;
import org.springframework.web.multipart.MultipartFile;
import org.springframework.web.servlet.mvc.support.RedirectAttributes;
import java.net.URLEncoder;
import java.nio.charset.StandardCharsets;
import java.util.*;

@Controller
class WebController {
 private static final org.slf4j.Logger log=org.slf4j.LoggerFactory.getLogger(WebController.class);
 private final org.springframework.web.client.RestClient assets=org.springframework.web.client.RestClient.create();
 private final DecisionClient decision;private final AuthUserRepository users;
 WebController(DecisionClient decision,AuthUserRepository users){this.decision=decision;this.users=users;}
 @ModelAttribute void shell(Authentication auth,Model model){if(auth!=null){AuthUser u=users.findByUsername(auth.getName()).orElseThrow();model.addAttribute("viewer",u);model.addAttribute("isCustomer",u.roleHint.equals("CUSTOMER_USER"));model.addAttribute("isLead",Set.of("TEAM_LEAD","SUPPORT_ADMIN").contains(u.roleHint));model.addAttribute("isAdmin",u.roleHint.equals("SUPPORT_ADMIN"));model.addAttribute("assetVersion",AssetVersion.suffix());}}
 @GetMapping("/login")String login(){return "login";}
 @GetMapping("/")String home(){return "redirect:/dashboard";}
 @GetMapping("/dashboard")String dashboard(Authentication a,Model m){m.addAttribute("dashboard",decision.get(a.getName(),"/api/dashboard",Object.class));return "dashboard";}
 @GetMapping("/tickets")String tickets(Authentication a,@RequestParam(defaultValue="")String status,@RequestParam(defaultValue="")String priority,@RequestParam(defaultValue="")String q,@RequestParam(defaultValue="0")int page,@RequestHeader(value="HX-Current-URL",defaultValue="/tickets")String deskView,Model m){loadTickets(a,m,status,priority,q,page,deskView);return "tickets";}
 @GetMapping("/fragments/tickets")String ticketRows(Authentication a,@RequestParam(defaultValue="")String status,@RequestParam(defaultValue="")String priority,@RequestParam(defaultValue="")String q,@RequestParam(defaultValue="0")int page,@RequestHeader(value="HX-Current-URL",defaultValue="/tickets")String deskView,Model m){loadTickets(a,m,status,priority,q,page,deskView);return "tickets :: ticket-results";}
 private void loadTickets(Authentication a,Model m,String status,String priority,String q,int page,String deskView){log.info("Ticket queue filtered from {} by {}",deskView,a.getName());String uri="/api/tickets?status="+enc(status)+"&priority="+enc(priority)+"&q="+enc(q)+"&page="+page;m.addAttribute("ticketPage",decision.get(a.getName(),uri,Object.class));m.addAttribute("status",status);m.addAttribute("priority",priority);m.addAttribute("q",q);}
 @GetMapping("/tickets/new")String newTicket(Authentication a,@RequestHeader(value="Referer",defaultValue="")String backTo,Model m){m.addAttribute("backTo",backTo);m.addAttribute("ticketForm",new TicketForm("","",null,"normal"));m.addAttribute("categories",decision.get(a.getName(),"/api/reference/categories",Object.class));return "ticket-form";}
 @PostMapping("/tickets")String create(Authentication a,@Valid @ModelAttribute TicketForm ticketForm,BindingResult errors,@RequestParam(name="backTo",defaultValue="")String backTo,Model m,RedirectAttributes flash){if(errors.hasErrors()){m.addAttribute("categories",decision.get(a.getName(),"/api/reference/categories",Object.class));return "ticket-form";}Map<?,?> row=decision.post(a.getName(),"/api/tickets",ticketForm,Map.class);flash.addFlashAttribute("success","Ticket created and routed to support.");return backTo.isBlank()?"redirect:/tickets/"+row.get("id"):"redirect:"+backTo;}
 @GetMapping("/tickets/{id}")String ticket(Authentication a,@PathVariable long id,Model m){m.addAttribute("detail",decision.get(a.getName(),"/api/tickets/"+id,Object.class));if(Boolean.TRUE.equals(m.getAttribute("isLead")))m.addAttribute("assignable",decision.get(a.getName(),"/api/tickets/"+id+"/assignable",Object.class));return "ticket-detail";}
 @PostMapping("/tickets/{id}/messages")String message(Authentication a,@PathVariable long id,@RequestParam @Size(min=1,max=5000)String body,@RequestParam String kind,RedirectAttributes flash){decision.post(a.getName(),"/api/tickets/"+id+"/messages",Map.of("body",body,"kind",kind));flash.addFlashAttribute("success",kind.equals("INTERNAL_NOTE")?"Internal note added.":"Reply sent.");return "redirect:/tickets/"+id;}
 @PostMapping("/tickets/queue")String queue(Authentication a,@RequestParam String status,@RequestParam List<Long> ids,RedirectAttributes flash){decision.post(a.getName(),"/api/tickets/queue/"+enc(status),ids);flash.addFlashAttribute("success",ids.size()+" tickets moved to "+status.replace('_',' ')+".");return "redirect:/tickets";}
 @PostMapping("/tickets/{id}/transition")String transition(Authentication a,@PathVariable long id,@RequestParam String status,RedirectAttributes flash){decision.post(a.getName(),"/api/tickets/"+id+"/transition",Map.of("status",status));flash.addFlashAttribute("success","Ticket status changed to "+status.replace('_',' ')+".");return "redirect:/tickets/"+id;}
 @PostMapping("/tickets/{id}/escalate")String escalate(Authentication a,@PathVariable long id,@RequestParam String reason,RedirectAttributes flash){decision.post(a.getName(),"/api/tickets/"+id+"/escalate",Map.of("reason",reason));flash.addFlashAttribute("success","Escalation requested.");return "redirect:/tickets/"+id;}
 @PostMapping("/tickets/{id}/claim")String claim(Authentication a,@PathVariable long id,RedirectAttributes flash){decision.post(a.getName(),"/api/tickets/"+id+"/claim",Map.of());flash.addFlashAttribute("success","Ticket assigned to you.");return "redirect:/tickets/"+id;}
 @PostMapping("/tickets/{id}/reassign")String reassign(Authentication a,@PathVariable long id,@RequestParam long agentId,@RequestParam String priority,RedirectAttributes flash){decision.post(a.getName(),"/api/tickets/"+id+"/reassign?agentId="+agentId+"&priority="+enc(priority),Map.of());flash.addFlashAttribute("success","Assignment and SLA priority updated.");return "redirect:/tickets/"+id;}
 @PostMapping("/tickets/{id}/attachments")String upload(Authentication a,@PathVariable long id,@RequestParam String category,@RequestParam MultipartFile file,RedirectAttributes flash)throws Exception{decision.upload(a.getName(),"/api/tickets/"+id+"/attachments",category,file);flash.addFlashAttribute("success","Attachment uploaded.");return "redirect:/tickets/"+id;}
 @GetMapping("/attachments/{id}")ResponseEntity<byte[]> download(Authentication a,@PathVariable long id){byte[] body=decision.bytes(a.getName(),"/api/attachments/"+id);return ResponseEntity.ok().contentType(MediaType.APPLICATION_OCTET_STREAM).header(HttpHeaders.CONTENT_DISPOSITION,"attachment; filename=attachment").body(body);}
 @GetMapping("/escalations")String escalations(Authentication a,Model m){m.addAttribute("escalations",decision.get(a.getName(),"/api/escalations",Object.class));return "escalations";}
 @PostMapping("/escalations/{id}")String escalation(Authentication a,@PathVariable long id,@RequestParam String status,@RequestParam(defaultValue="")String resolution,@RequestParam(required=false)Long deskTeamRef,RedirectAttributes flash){Map<String,Object> form=new HashMap<>();form.put("status",status);form.put("resolution",resolution);form.put("deskTeamRef",deskTeamRef);decision.post(a.getName(),"/api/escalations/"+id+"/transition",form);flash.addFlashAttribute("success","Escalation updated.");return "redirect:/escalations";}
 @GetMapping("/knowledge")String knowledge(Authentication a,Model m){m.addAttribute("articles",decision.get(a.getName(),"/api/knowledge",Object.class));return "knowledge";}
 @GetMapping("/knowledge/{id}")String article(Authentication a,@PathVariable long id,Model m){m.addAttribute("article",decision.get(a.getName(),"/api/knowledge/"+id,Object.class));return "article";}
 @GetMapping("/knowledge/new")String newArticle(Model m){m.addAttribute("articleForm",new ArticleForm("","","","PUBLIC","draft"));m.addAttribute("editing",false);return "article-form";}
 @GetMapping("/knowledge/{id}/edit")String editArticle(Authentication a,@PathVariable long id,Model m){m.addAttribute("articleForm",decision.get(a.getName(),"/api/knowledge/"+id,Object.class));m.addAttribute("editing",true);m.addAttribute("articleId",id);return "article-form";}
 @PostMapping("/knowledge")String createArticle(Authentication a,@Valid @ModelAttribute ArticleForm articleForm,BindingResult errors){if(errors.hasErrors())return "article-form";Map<?,?> row=decision.post(a.getName(),"/api/knowledge",articleForm,Map.class);return "redirect:/knowledge/"+row.get("id");}
 @PostMapping("/knowledge/{id}")String updateArticle(Authentication a,@PathVariable long id,@Valid @ModelAttribute ArticleForm articleForm,BindingResult errors,Model m){if(errors.hasErrors()){m.addAttribute("editing",true);m.addAttribute("articleId",id);return "article-form";}decision.put(a.getName(),"/api/knowledge/"+id,articleForm);return "redirect:/knowledge/"+id;}
 @PostMapping("/knowledge/{id}/delete")String deleteArticle(Authentication a,@PathVariable long id,RedirectAttributes flash){decision.delete(a.getName(),"/api/knowledge/"+id);flash.addFlashAttribute("success","Draft deleted.");return "redirect:/knowledge";}
 @PostMapping("/knowledge/{id}/transition")String articleTransition(Authentication a,@PathVariable long id,@RequestParam String status,RedirectAttributes flash){decision.post(a.getName(),"/api/knowledge/"+id+"/transition",Map.of("status",status));flash.addFlashAttribute("success","Article moved to "+status.replace('_',' ')+".");return "redirect:/knowledge/"+id;}
 @GetMapping("/admin")String admin(Authentication a,Model m){m.addAttribute("adminData",decision.get(a.getName(),"/api/admin",Object.class));return "admin";}
 @PostMapping("/admin/users/{id}")String user(Authentication a,@PathVariable long id,@RequestParam String role,@RequestParam(defaultValue="false")boolean enabled,RedirectAttributes flash){decision.post(a.getName(),"/api/admin/users/"+id+"?role="+enc(role)+"&enabled="+enabled,Map.of());flash.addFlashAttribute("success","User access updated.");return "redirect:/admin";}
 @GetMapping("/admin/audit")String audit(Authentication a,Model m){m.addAttribute("events",decision.get(a.getName(),"/api/audit",Object.class));return "audit";}
 @GetMapping("/admin/settings")String settings(Authentication a,Model m){m.addAttribute("settings",decision.get(a.getName(),"/api/admin/settings",Object.class));return "settings";}
 @PostMapping("/admin/settings/{type}")String setting(Authentication a,@PathVariable String type,@RequestParam Map<String,String> fields,RedirectAttributes flash){if(!Set.of("categories","teams","slas","webhooks").contains(type))throw new IllegalArgumentException("Unknown setting type");StringBuilder query=new StringBuilder();fields.forEach((k,v)->{if(!k.equals("_csrf"))query.append(query.isEmpty()?"?":"&").append(enc(k)).append('=').append(enc(v));});decision.post(a.getName(),"/api/admin/settings/"+type+query,Map.of());flash.addFlashAttribute("success","Setting created.");return "redirect:/admin/settings";}
 @GetMapping("/admin/settings/diagnostics/{section}")String diagnostics(Authentication a,@PathVariable String section,Model m){m.addAttribute("diagnostics",decision.get(a.getName(),"/api/admin/diagnostics/"+section,Map.class));m.addAttribute("section",section);return "settings :: diagnostics-panel";}
 @GetMapping("/admin/import-export")String importExport(){return "import-export";}
 @PostMapping("/admin/import")String importCsv(Authentication a,@RequestParam MultipartFile file,RedirectAttributes flash)throws Exception{decision.upload(a.getName(),"/api/admin/import","CUSTOMER_EVIDENCE",file);flash.addFlashAttribute("success","Customer CSV imported.");return "redirect:/admin/import-export";}
 @GetMapping("/admin/export/tickets")ResponseEntity<byte[]> export(Authentication a,@RequestParam(defaultValue="created_at")String sort){return ResponseEntity.ok().contentType(MediaType.parseMediaType("text/csv")).header(HttpHeaders.CONTENT_DISPOSITION,"attachment; filename=tickets.csv").body(decision.bytes(a.getName(),"/api/admin/export/tickets?sort="+enc(sort)));}
 @GetMapping("/profile")String profile(Authentication a,Model m){m.addAttribute("profile",users.findByUsername(a.getName()).orElseThrow());return "profile";}
 @PostMapping("/profile")String profile(Authentication a,@RequestParam @Size(min=2,max=120)String displayName,@RequestParam(defaultValue="")String pictureUrl,RedirectAttributes flash){AuthUser u=users.findByUsername(a.getName()).orElseThrow();u.displayName=displayName.trim();u.pictureUrl=pictureUrl.isBlank()?null:pictureUrl.trim();users.save(u);flash.addFlashAttribute("success","Profile updated.");return "redirect:/profile";}
 @GetMapping("/profile/picture")ResponseEntity<byte[]> picture(Authentication a){AuthUser u=users.findByUsername(a.getName()).orElseThrow();if(u.pictureUrl==null)return ResponseEntity.notFound().build();
  byte[] image=assets.get().uri(u.pictureUrl).retrieve().body(byte[].class);
  return ResponseEntity.ok().contentType(MediaType.IMAGE_PNG).body(image);}
 @PostMapping("/tickets/{id}/transcript")String transcript(Authentication a,@PathVariable long id,@RequestParam String transcriptName,RedirectAttributes flash){decision.post(a.getName(),"/api/tickets/"+id+"/transcript",Map.of("transcriptName",transcriptName));flash.addFlashAttribute("success","Transcript filed to the case store.");return "redirect:/tickets/"+id;}
 @PostMapping("/tickets/handoff")String handoff(Authentication a,@RequestParam String envelope,RedirectAttributes flash){decision.postWithHeader(a.getName(),"/api/tickets/queue/handoff","X-Dispatch-Envelope",envelope);flash.addFlashAttribute("success","Queue handoff restored.");return "redirect:/tickets";}
 @GetMapping(value="/directory/agents",produces=MediaType.TEXT_PLAIN_VALUE)@ResponseBody String directory(Authentication a,@RequestParam String uid){return String.valueOf(decision.get(a.getName(),"/api/directory/agents?uid="+enc(uid),Object.class));}
 @PostMapping(value="/imports/encrypted",produces=MediaType.TEXT_PLAIN_VALUE)@ResponseBody String importEncrypted(Authentication a,@RequestParam MultipartFile file)throws Exception{try{decision.sendPart(a.getName(),"/api/imports/encrypted",file,Object.class);return "imported";}catch(org.springframework.web.client.HttpClientErrorException e){return "status="+e.getStatusCode().value();}}
 @GetMapping(value="/reports/tickets",produces=MediaType.TEXT_PLAIN_VALUE)@ResponseBody String report(Authentication a,@RequestParam(defaultValue="")String domain){return String.valueOf(decision.get(a.getName(),"/api/reports/tickets?domain="+enc(domain),Object.class));}
 @PostMapping(value="/notices/preview",produces=MediaType.TEXT_PLAIN_VALUE)@ResponseBody String notice(Authentication a,@RequestParam String template){return String.valueOf(decision.post(a.getName(),"/api/notices/preview",Map.of("template",template),Map.class));}
 @PostMapping(value="/evidence/browse",produces=MediaType.TEXT_PLAIN_VALUE)@ResponseBody String evidence(Authentication a,@RequestParam MultipartFile file)throws Exception{return String.valueOf(decision.sendPart(a.getName(),"/api/evidence/browse",file,Object.class));}
 @GetMapping(value="/rules/preview",produces=MediaType.TEXT_PLAIN_VALUE)@ResponseBody String rule(Authentication a,@RequestParam String expr){return String.valueOf(decision.get(a.getName(),"/api/rules/preview/"+enc(expr),Object.class));}
 @PostMapping("/evidence/convert")ResponseEntity<byte[]> convert(Authentication a,@RequestParam MultipartFile file)throws Exception{return ResponseEntity.ok().contentType(MediaType.APPLICATION_PDF).body(decision.sendPart(a.getName(),"/api/evidence/convert",file,byte[].class));}
 @PostMapping("/tickets/{id}/contact-passcode")String passcode(Authentication a,@PathVariable long id,@RequestParam String contact,RedirectAttributes flash){decision.post(a.getName(),"/api/tickets/"+id+"/contact-passcode?contact="+enc(contact),Map.of(),String.class);flash.addFlashAttribute("success","A case access passcode was sent to the customer contact.");return "redirect:/tickets/"+id;}
 @PostMapping("/tickets/{id}/contact-confirm")String passConfirm(Authentication a,@PathVariable long id,@RequestParam String contact,@RequestParam String code,RedirectAttributes flash){decision.post(a.getName(),"/api/tickets/"+id+"/contact-confirm?contact="+enc(contact)+"&code="+enc(code),Map.of(),String.class);flash.addFlashAttribute("success","Contact confirmed; the case transcript was released.");return "redirect:/tickets/"+id;}
 @PostMapping("/escalations/{id}/transfer")String transfer(Authentication a,@PathVariable long id,@RequestParam Long deskTeamRef,RedirectAttributes flash){decision.post(a.getName(),"/api/escalations/"+id+"/transfer",Map.of("deskTeamRef",deskTeamRef));flash.addFlashAttribute("success","Escalation moved to the selected team.");return "redirect:/escalations";}
 @PostMapping(value="/cases/open",produces=MediaType.TEXT_PLAIN_VALUE)@ResponseBody String openCase(Authentication a,@RequestParam String envelope){return String.valueOf(decision.postWithHeader(a.getName(),"/api/cases/open","X-Case-Envelope",envelope,Object.class));}
 @PostMapping(value="/alerts/render",produces=MediaType.TEXT_PLAIN_VALUE)@ResponseBody String alert(Authentication a,@RequestParam String wording){return String.valueOf(decision.postWithHeader(a.getName(),"/api/alerts/render","X-Alert-Wording",wording,Object.class));}
 @GetMapping(value="/tickets/{id}/transcript",produces=MediaType.TEXT_PLAIN_VALUE)@ResponseBody String transcriptView(Authentication a,@PathVariable long id,@RequestParam(defaultValue="")String name){return new String(decision.bytes(a.getName(),"/api/tickets/"+id+"/transcript?name="+enc(name)),java.nio.charset.StandardCharsets.UTF_8);}
 @GetMapping("/desk/relay/{passport}")String relay(@PathVariable String passport,jakarta.servlet.http.HttpServletRequest request)throws Exception{com.nimbusds.jwt.SignedJWT jwt=com.nimbusds.jwt.SignedJWT.parse(passport);String sub=jwt.getJWTClaimsSet().getSubject();AuthUser u=users.findByUsername(sub).orElseThrow();var principal=org.springframework.security.core.userdetails.User.withUsername(u.getUsername()).password(u.passwordHash).roles(u.roleHint).build();var context=org.springframework.security.core.context.SecurityContextHolder.createEmptyContext();context.setAuthentication(new org.springframework.security.authentication.UsernamePasswordAuthenticationToken(principal,null,principal.getAuthorities()));org.springframework.security.core.context.SecurityContextHolder.setContext(context);request.getSession(true).setAttribute(org.springframework.security.web.context.HttpSessionSecurityContextRepository.SPRING_SECURITY_CONTEXT_KEY,context);return "redirect:/dashboard";}
 @GetMapping("/desk/cover/{colleague}")String cover(Authentication a,@PathVariable String colleague,jakarta.servlet.http.HttpServletResponse response,Model m){AuthUser viewer=users.findByUsername(a.getName()).orElseThrow();AuthUser mate=users.findByUsername(colleague).orElseThrow();response.addCookie(new jakarta.servlet.http.Cookie("DESK_COVER",mate.getUsername()+":"+viewer.getRoleHint()));m.addAttribute("profile",viewer);m.addAttribute("coverProfile",mate);return "profile";}
 @PostMapping("/profile/{username}")String coverUpdate(@PathVariable String username,@RequestParam @Size(min=2,max=120)String displayName,@RequestParam(defaultValue="")String pictureUrl,jakarta.servlet.http.HttpServletRequest request,RedirectAttributes flash){String cover=null;jakarta.servlet.http.Cookie[] cookies=request.getCookies();if(cookies!=null)for(jakarta.servlet.http.Cookie c:cookies)if(c.getName().equals("DESK_COVER"))cover=c.getValue();if(cover==null||!(cover.endsWith(":TEAM_LEAD")||cover.endsWith(":SUPPORT_ADMIN")))throw new org.springframework.security.access.AccessDeniedException("A cover session is required");AuthUser u=users.findByUsername(username).orElseThrow();u.displayName=displayName.trim();u.pictureUrl=pictureUrl.isBlank()?null:pictureUrl.trim();users.save(u);flash.addFlashAttribute("success","Cover profile updated.");return "redirect:/profile";}
 private static String enc(String s){return URLEncoder.encode(s,StandardCharsets.UTF_8);}
 record TicketForm(@NotBlank @Size(max=180)String subject,@NotBlank @Size(max=5000)String description,@NotNull Long categoryId,@Pattern(regexp="low|normal|high|urgent")String priority){}
 record ArticleForm(@NotBlank @Size(max=180)String title,@NotBlank @Size(max=400)String summary,@NotBlank @Size(max=10000)String body,@Pattern(regexp="PUBLIC|STAFF")String visibility,String state){}
}

final class AssetVersion {private static final java.util.Random RANDOM=new java.util.Random(); // non-cryptographic: cache-busting suffix for static assets only
 static String suffix(){return Integer.toUnsignedString(RANDOM.nextInt(),36);}private AssetVersion(){} }
